package com.medtrack.batch.service; import com.medtrack.batch.dto.*; import com.medtrack.batch.entity.*; import com.medtrack.batch.repository.BatchRepository; import com.medtrack.medicine.entity.*; import com.medtrack.medicine.repository.MedicineRepository; import com.medtrack.shared.exception.*; import com.medtrack.supplier.entity.Supplier; import com.medtrack.supplier.repository.SupplierRepository; import java.time.LocalDate; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class BatchService {private final BatchRepository batches;private final MedicineRepository medicines;private final SupplierRepository suppliers; public BatchService(BatchRepository b,MedicineRepository m,SupplierRepository s){batches=b;medicines=m;suppliers=s;} public BatchResponse create(BatchRequest r){Medicine m=medicines.findById(r.medicineId()).orElseThrow(()->new NotFoundException("Medicine"));if(m.getStatus()!=MedicineStatus.ACTIVE)throw new DomainException("MEDICINE_DISCONTINUED","Discontinued medicines cannot receive new batches");if(batches.existsByMedicine_IdAndBatchNumber(m.getId(),r.batchNumber()))throw new DomainException("DUPLICATE_BATCH_NUMBER","Batch number already exists for this medicine");if(!r.expiryDate().isAfter(r.manufacturingDate()))throw new DomainException("BATCH_EXPIRY_INVALID","Batch expiry date must be after manufacturing date");LocalDate minimum=LocalDate.now().plusDays(m.getMinReceivingShelfLifeDays());if(r.expiryDate().isBefore(minimum))throw new DomainException("BATCH_EXPIRY_TOO_SOON","Batch expiry date fails minimum receiving shelf-life requirement ("+m.getMinReceivingShelfLifeDays()+" days required)");Supplier s=suppliers.findById(r.supplierId()).orElseThrow(()->new NotFoundException("Supplier"));return BatchResponse.of(batches.save(new Batch(r.batchNumber(),m,s,r.manufacturingDate(),r.expiryDate(),r.initialQuantity(),r.status()==null?BatchStatus.ACTIVE:BatchStatus.valueOf(r.status()))));} @Transactional(readOnly=true) public Page<BatchResponse> list(Pageable p){return batches.findAll(p).map(BatchResponse::of);} @Transactional(readOnly=true) public BatchResponse get(UUID id){return BatchResponse.of(batches.findById(id).orElseThrow(()->new NotFoundException("Batch")));}}
